120	/// Total encoded length of a share envelope in bytes.
121	pub const SHARE_ENVELOPE_LEN: usize = 42;
122	
123	const ENVELOPE_PAYLOAD_LEN: usize = 32;
124	const ENVELOPE_CHECKSUM_LEN: usize = 4;
125	/// Length of the bytes the checksum covers: everything before the checksum (version + set_id +
126	/// index + payload).
127	const ENVELOPE_PREIMAGE_LEN: usize = SHARE_ENVELOPE_LEN - ENVELOPE_CHECKSUM_LEN; // 38
128	
129	/// A self-describing Shamir share (version 2).
130	///
131	/// Wraps a raw [`ShamirShare`] payload with the metadata needed to combine it safely: a `set_id`
132	/// that identifies the split it came from and the share `index`. The `payload` is secret material
133	/// and is zeroized on drop.
134	pub struct ShareEnvelope {
135	    /// Envelope format version. Always [`SHARE_ENVELOPE_VERSION`] for envelopes this crate builds.
136	    version: u8,
137	    /// Identifies the split (generation) these three shares belong to. Shares with differing
138	    /// `set_id` values must never be combined.
139	    set_id: u32,
140	    /// Share index in `[1, 3]`. Not secret.
141	    index: u8,
142	    /// 32 bytes of Shamir share data. Zeroized on drop.
143	    payload: Zeroizing<[u8; 32]>,
144	}
145	
146	// Redacts the secret payload — a `ShareEnvelope` carries share material that must never land in a
147	// log or panic message. Only the non-secret metadata is shown.
148	impl std::fmt::Debug for ShareEnvelope {
149	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
150	        f.debug_struct("ShareEnvelope")
151	            .field("version", &self.version)
152	            .field("set_id", &self.set_id)
153	            .field("index", &self.index)
154	            .field("payload", &"<redacted>")
155	            .finish()
156	    }
157	}
158	
159	impl ShareEnvelope {
160	    /// Envelope format version (always [`SHARE_ENVELOPE_VERSION`] for envelopes this crate builds).
161	    pub fn version(&self) -> u8 {
162	        self.version
163	    }
164	
165	    /// The split (generation) identifier these three shares share.
166	    pub fn set_id(&self) -> u32 {
167	        self.set_id
168	    }
169	
170	    /// Share index in `[1, 3]`. Not secret.
171	    pub fn index(&self) -> u8 {
172	        self.index
173	    }
174	
175	    /// Wrap a raw [`ShamirShare`] into a versioned envelope tied to `set_id`.
176	    fn from_share(set_id: u32, share: &ShamirShare) -> Self {
177	        ShareEnvelope {
178	            version: SHARE_ENVELOPE_VERSION,
179	            set_id,
180	            index: share.index,
181	            payload: share.data.clone(),
182	        }
183	    }
184	
185	    /// The bytes the checksum is computed over: `version || set_id || index || payload`.
186	    fn preimage(&self) -> Zeroizing<[u8; ENVELOPE_PREIMAGE_LEN]> {
187	        let mut buf = Zeroizing::new([0u8; ENVELOPE_PREIMAGE_LEN]);
188	        buf[0] = self.version;
189	        buf[1..5].copy_from_slice(&self.set_id.to_be_bytes());
190	        buf[5] = self.index;
191	        buf[6..ENVELOPE_PREIMAGE_LEN].copy_from_slice(self.payload.as_slice());
192	        buf
193	    }
194	
195	    /// Serialize to the full 42-byte envelope, appending a freshly computed checksum.
196	    pub fn to_bytes(&self) -> Zeroizing<[u8; SHARE_ENVELOPE_LEN]> {
197	        let preimage = self.preimage();
198	        let checksum = envelope_checksum(preimage.as_slice());
199	        let mut out = Zeroizing::new([0u8; SHARE_ENVELOPE_LEN]);
200	        out[..ENVELOPE_PREIMAGE_LEN].copy_from_slice(preimage.as_slice());
201	        out[ENVELOPE_PREIMAGE_LEN..].copy_from_slice(&checksum);
202	        out
203	    }
204	
205	    /// Parse a 42-byte envelope, validating length, version, and checksum.
206	    ///
207	    /// # Errors
208	    /// - [`CryptoError::ShareFormat`] if the length or index is invalid.
209	    /// - [`CryptoError::ShareVersion`] if the version byte is not [`SHARE_ENVELOPE_VERSION`].
210	    /// - [`CryptoError::ShareChecksum`] if the trailing checksum does not match the body.
211	    ///
212	    /// Version is checked before the checksum so a future-version share reports a version error
213	    /// (actionable: "upgrade / use the right tool") rather than a generic corruption error.
214	    pub fn from_bytes(bytes: &[u8]) -> Result<Self, CryptoError> {
215	        if bytes.len() != SHARE_ENVELOPE_LEN {
216	            return Err(CryptoError::ShareFormat(format!(
217	                "expected {SHARE_ENVELOPE_LEN} bytes, got {}",
218	                bytes.len()
219	            )));
220	        }
221	
222	        let version = bytes[0];
223	        if version != SHARE_ENVELOPE_VERSION {
224	            return Err(CryptoError::ShareVersion(format!(
225	                "got version {version}, expected {SHARE_ENVELOPE_VERSION}"
226	            )));
227	        }
228	
229	        let (preimage, checksum) = bytes.split_at(ENVELOPE_PREIMAGE_LEN);
230	        let expected = envelope_checksum(preimage);
231	        // Constant-time-ish is unnecessary here: the checksum is public integrity metadata, not a
232	        // secret. A plain compare is fine.
233	        if checksum != expected {
234	            return Err(CryptoError::ShareChecksum(
235	                "trailing checksum does not match envelope body".to_string(),
236	            ));
237	        }
238	
239	        let set_id = u32::from_be_bytes([bytes[1], bytes[2], bytes[3], bytes[4]]);
240	        let index = bytes[5];
241	        if index == 0 || index > 3 {
242	            return Err(CryptoError::ShareFormat(format!(
243	                "share index must be in [1, 3], got {index}"
244	            )));
245	        }
246	
247	        let mut payload = Zeroizing::new([0u8; ENVELOPE_PAYLOAD_LEN]);
248	        payload.copy_from_slice(&bytes[6..ENVELOPE_PREIMAGE_LEN]);
249	
250	        Ok(ShareEnvelope {
251	            version,
252	            set_id,
253	            index,
254	            payload,
255	        })
256	    }
257	
258	    /// Encode the envelope as an uppercase, unpadded base32 string (RFC 4648).
259	    ///
260	    /// Uppercase base32 uses only characters in QR codes' alphanumeric mode, keeping machine shares
261	    /// (Shares 1 and 2) compact when rendered as a QR code. The encoded form is share material, so
262	    /// it is returned in a [`Zeroizing`] buffer that scrubs the heap allocation on drop.
263	    pub fn encode_share(&self) -> Zeroizing<String> {
264	        Zeroizing::new(data_encoding::BASE32_NOPAD.encode(self.to_bytes().as_slice()))
265	    }
266	
267	    /// Decode a share from its base32 string form (as produced by [`encode_share`]).
268	    ///
269	    /// Surrounding whitespace is ignored and lowercase input is accepted. Returns the same
270	    /// distinct errors as [`from_bytes`], plus [`CryptoError::ShareFormat`] for non-base32 input.
271	    ///
272	    /// [`encode_share`]: ShareEnvelope::encode_share
273	    /// [`from_bytes`]: ShareEnvelope::from_bytes
274	    pub fn decode_share(encoded: &str) -> Result<Self, CryptoError> {
275	        // The normalized copy is share material; keep it in zeroizing storage.
276	        let normalized = Zeroizing::new(
277	            encoded
278	                .chars()
279	                .filter(|c| !c.is_whitespace())
280	                .collect::<String>()
281	                .to_ascii_uppercase(),
282	        );
283	        let bytes = data_encoding::BASE32_NOPAD
284	            .decode(normalized.as_bytes())
285	            .map_err(|e| CryptoError::ShareFormat(format!("invalid base32: {e}")))?;
286	        Self::from_bytes(&bytes)
287	    }
288	
289	    /// Render the envelope as a BIP-39-style mnemonic phrase for the human-custody share (Share 3).
290	    ///
291	    /// The whole 42-byte envelope — including its checksum — is encoded, so a phrase is
292	    /// self-describing exactly like the base32 form and can be combined with a machine share. The
293	    /// phrase is share material, so it is returned in a [`Zeroizing`] buffer.
294	    pub fn encode_share_words(&self) -> Zeroizing<String> {
295	        bytes_to_words(self.to_bytes().as_slice())
296	    }
297	
298	    /// Parse a mnemonic phrase produced by [`encode_share_words`] back into an envelope.
299	    ///
300	    /// Returns [`CryptoError::ShareFormat`] for an unknown word, and the same version/checksum
301	    /// errors as [`from_bytes`] once the words decode to bytes.
302	    ///
303	    /// [`encode_share_words`]: ShareEnvelope::encode_share_words
304	    /// [`from_bytes`]: ShareEnvelope::from_bytes
305	    pub fn decode_share_words(phrase: &str) -> Result<Self, CryptoError> {
306	        let bytes = words_to_bytes(phrase)?;
307	        Self::from_bytes(&bytes)
308	    }
309	}
310	
311	/// First 4 bytes of SHA-256 over the envelope preimage.
312	fn envelope_checksum(preimage: &[u8]) -> [u8; ENVELOPE_CHECKSUM_LEN] {
313	    let digest = Sha256::digest(preimage);
314	    let mut checksum = [0u8; ENVELOPE_CHECKSUM_LEN];
315	    checksum.copy_from_slice(&digest[..ENVELOPE_CHECKSUM_LEN]);
316	    checksum
317	}
