319	/// Split a 32-byte secret into 3 self-describing share envelopes tied to `set_id`.
320	///
321	/// The GF(2^8) split is identical to [`split_secret`]; each resulting share is wrapped in a v2
322	/// envelope carrying `set_id` and its index. The caller supplies `set_id` (typically a fresh
323	/// random value per split) so the three envelopes of one generation can be told apart from a later
324	/// re-split's — see [`combine_envelopes`].
325	pub fn split_secret_into_envelopes(
326	    secret: &[u8; 32],
327	    set_id: u32,
328	) -> Result<[ShareEnvelope; 3], CryptoError> {
329	    let shares = split_secret(secret)?;
330	    Ok([
331	        ShareEnvelope::from_share(set_id, &shares[0]),
332	        ShareEnvelope::from_share(set_id, &shares[1]),
