1	/**
2	 * Stateful in-memory fake for the identity-wallet harness (browser test mode).
3	 *
4	 * Pure TypeScript: no Tauri, no DOM, no network — so it is unit-testable in the
5	 * Node vitest environment (see `state.test.ts`). The registry (`registry.ts`) owns
6	 * the command→handler mapping and mutates a {@link WalletState} instance through the
7	 * helpers here; scenarios (`scenarios.ts`) seed fresh states from presets.
8	 *
9	 * The domain modeled mirrors what the wallet's screens actually read: managed
10	 * identities (each with a PLC-format DID document, a device key, PLC-monitor alerts,
11	 * and bound agents), plus the transient state the multi-step create / claim /
12	 * migration flows thread across commands.
13	 */
14	import type { UnauthorizedChange } from '$lib/ipc';
15	import type {
16	  AgentSummary,
17	  AgentAuditEvent,
18	  AppPasswordEntry,
19	} from '$lib/ipc';
20	
21	/** A `did:key` multibase string that is stable for a given seed (not a real key). */
22	export function fakeDeviceKeyId(seed: string): string {
23	  return `did:key:zHarnessDev${hashToken(seed)}`;
24	}
25	
26	/** A plausible-looking `did:plc` for a given seed. */
27	export function fakePlcDid(seed: string): string {
28	  return `did:plc:harness${hashToken(seed)}`;
29	}
30	
31	/** Deterministic base36-ish token from a string — keeps fakes readable and stable. */
32	function hashToken(seed: string): string {
33	  let h = 2166136261;
34	  for (let i = 0; i < seed.length; i++) {
35	    h = (h ^ seed.charCodeAt(i)) >>> 0;
36	    h = (h * 16777619) >>> 0;
37	  }
38	  return h.toString(36).padStart(7, '0').slice(0, 12);
39	}
40	
41	/** One agent bound to an identity, plus its append-only audit trail. */
42	export interface FakeAgent {
43	  summary: AgentSummary;
44	  audit: AgentAuditEvent[];
45	}
46	
47	/** One managed identity as the fake models it. */
48	export interface FakeIdentity {
49	  did: string;
50	  handle: string;
51	  pdsUrl: string;
52	  /** `did:key` of this identity's device key. */
53	  deviceKeyId: string;
54	  /** PLC rotation keys, `rotationKeys[0]` === deviceKeyId when the device is root. */
55	  rotationKeys: string[];
56	  /** PLC-monitor alerts surfaced on the home screen. */
57	  alerts: UnauthorizedChange[];
58	  /** Agents bound to this identity ("My agents"). */
59	  agents: FakeAgent[];
60	  /** App passwords minted for this identity (metadata only, like the real list route). */
61	  appPasswords: AppPasswordEntry[];
62	}
63	
64	/** Transient state for the multi-step import (claim) flow. */
65	export interface ClaimFlow {
66	  did: string;
67	  handle: string;
68	  pdsUrl: string;
69	  authenticated: boolean;
70	  verificationRequested: boolean;
71	}
72	
73	/** Transient state for the wallet-authorized outbound migration flow. */
74	export interface MigrationFlow {
75	  did: string;
76	  destPdsUrl: string;
77	  sourceAuthenticated: boolean;
78	  destinationCreated: boolean;
79	  repoTransferred: boolean;
80	  blobsTransferred: boolean;
81	  preferencesTransferred: boolean;
82	  verified: boolean;
83	  armed: boolean;
84	}
85	
86	/** Transient state for the create flow (account → DID ceremony → handle). */
87	export interface CreateFlow {
88	  claimCode?: string;
89	  email?: string;
90	  handle?: string;
91	  did?: string;
92	}
93	
94	/** The full wallet fake store. */
95	export interface WalletState {
96	  /** Configured PDS base URL, or null on first launch (drives the config screen). */
97	  pdsUrl: string | null;
98	  /** Available handle domains the configured PDS offers. */
99	  availableUserDomains: string[];
100	  appearance: 'system' | 'light' | 'dark' | null;
101	  biometricEnabled: boolean;
102	  identities: FakeIdentity[];
103	  create: CreateFlow | null;
104	  claim: ClaimFlow | null;
105	  migration: MigrationFlow | null;
106	}
107	
108	/** The default PDS the fake reports once configured. */
109	export const DEFAULT_PDS_URL = 'https://harness.pds.local';
110	
111	/** A fresh, empty wallet state (fresh-install baseline). */
112	export function emptyWalletState(): WalletState {
113	  return {
114	    pdsUrl: null,
115	    availableUserDomains: ['.harness.pds.local'],
116	    appearance: null,
117	    biometricEnabled: true,
118	    identities: [],
119	    create: null,
120	    claim: null,
121	    migration: null,
122	  };
123	}
124	
125	/** Build a PLC-format DID document for an identity (the shape the home screen reads). */
126	export function makeDidDoc(identity: FakeIdentity): Record<string, unknown> {
127	  return {
128	    did: identity.did,
129	    alsoKnownAs: [`at://${identity.handle}`],
130	    rotationKeys: identity.rotationKeys,
131	    verificationMethods: {
132	      atproto: identity.rotationKeys[0] ?? identity.deviceKeyId,
133	    },
134	    services: {
135	      atproto_pds: {
136	        type: 'AtprotoPersonalDataServer',
137	        endpoint: identity.pdsUrl,
138	      },
139	    },
140	  };
141	}
142	
143	/**
144	 * Seed a fresh identity. `deviceKeyIsRoot` controls whether the device key sits at
145	 * `rotationKeys[0]` — the "Root key" badge on the home card depends on this.
146	 */
