286	    async fn audit_events(db: &sqlx::SqlitePool, did: &str) -> Vec<String> {
287	        sqlx::query_scalar(
288	            "SELECT event_type FROM recovery_audit_events WHERE did = ? ORDER BY rowid",
289	        )
290	        .bind(did)
291	        .fetch_all(db)
292	        .await
293	        .unwrap()
294	    }
