304	    #[tokio::test]
305	    async fn deposit_replace_delete_lifecycle_with_audit_trail() {
306	        let state = escrow_state().await;
307	        let did = "did:plc:escrowroute";
308	        seed_account(&state.db, did).await;
309	        let headers = session_headers(&state.db, did).await;
310	
311	        // Deposit.
312	        let share_a = share_envelope(1, 1);
313	        assert_eq!(
314	            put_share(&state, &headers, &share_a).await.unwrap(),
315	            "deposited"
316	        );
317	
318	        // The stored ciphertext is wrapped — the raw row never contains the share, and it
319	        // unwraps back to the exact envelope bytes under the master key.
320	        let (stored_share, _) = stored_row(&state.db, did).await.unwrap();
321	        assert!(!stored_share.contains(&share_a));
322	        let unwrapped = crypto::decrypt_secret_bytes(&stored_share, &test_master_key()).unwrap();
323	        let envelope = crypto::ShareEnvelope::from_bytes(&unwrapped).unwrap();
324	        assert_eq!(envelope.set_id(), 1);
325	        assert_eq!(envelope.index(), 2);
326	
327	        // Replace (rotation epilogue / re-key).
328	        let share_b = share_envelope(2, 1);
329	        assert_eq!(
330	            put_share(&state, &headers, &share_b).await.unwrap(),
331	            "rotated"
332	        );
333	        let (stored_share, rotated_at) = stored_row(&state.db, did).await.unwrap();
334	        let unwrapped = crypto::decrypt_secret_bytes(&stored_share, &test_master_key()).unwrap();
335	        assert_eq!(
