340	            "the replacement generation must be stored"
341	        );
342	        assert!(rotated_at.is_some());
343	
344	        // Delete (opt-out), then the idempotent repeat.
345	        assert_eq!(delete_share(&state, &headers).await.unwrap(), "deleted");
346	        assert!(stored_row(&state.db, did).await.is_none());
347	        assert_eq!(delete_share(&state, &headers).await.unwrap(), "deleted");
348	
349	        assert_eq!(
350	            audit_events(&state.db, did).await,
351	            vec!["deposited", "rotated", "deleted"],
352	            "one event per real state change; the repeat delete adds none"
353	        );
354	    }
