356	    #[tokio::test]
357	    async fn malformed_and_wrong_index_shares_are_refused() {
358	        let state = escrow_state().await;
359	        let did = "did:plc:escrowbadshare";
360	        seed_account(&state.db, did).await;
361	        let headers = session_headers(&state.db, did).await;
362	
363	        let err = put_share(&state, &headers, "NOT-A-SHARE")
364	            .await
365	            .unwrap_err();
366	        assert_eq!(err.status_code(), 400);
367	
368	        // Share 3 (index 3) is the user's copy — the escrow refuses it.
369	        let share_3 = share_envelope(1, 2);
370	        let err = put_share(&state, &headers, &share_3).await.unwrap_err();
371	        assert_eq!(err.status_code(), 400);
372	
373	        assert!(
374	            audit_events(&state.db, did).await.is_empty(),
375	            "refused deposits leave no state and no audit rows"
376	        );
377	    }
378	
379	    #[tokio::test]
380	    async fn unauthenticated_requests_are_rejected() {
381	        let state = escrow_state().await;
382	        let headers = HeaderMap::new();
383	
384	        let err = put_share(&state, &headers, &share_envelope(1, 1))
385	            .await
386	            .unwrap_err();
387	        assert_eq!(err.status_code(), 401);
388	        let err = delete_share(&state, &headers).await.unwrap_err();
389	        assert_eq!(err.status_code(), 401);
390	    }
391	
392	    #[tokio::test]
393	    async fn missing_master_key_is_service_unavailable() {
394	        let state = test_state().await; // no master key configured
395	        let did = "did:plc:escrownokey";
396	        seed_account(&state.db, did).await;
397	        let headers = session_headers(&state.db, did).await;
398	
399	        let err = put_share(&state, &headers, &share_envelope(1, 1))
400	            .await
401	            .unwrap_err();
402	        assert_eq!(err.status_code(), 503);
403	    }
404	}
