77	/// The staging slot's JSON payload. The seed is deliberately absent — it is
78	/// `combine_envelopes(share1, share2)`, so storing it again would only widen the
79	/// secret surface.
80	///
81	/// The share fields are share material held in plain `String`s while the record is
82	/// (de)serialized, so the record wipes them on drop (`Drop` below) — the same rule as
83	/// every other in-memory home of share material.
84	#[derive(Serialize, Deserialize)]
85	struct StagingRecord {
86	    version: u32,
87	    /// The ceremony inputs this set was generated for. A retry with different inputs
88	    /// (different handle, different PDS) is a different ceremony — regenerate.
