156	/// Read and validate the staging slot.
157	///
158	/// Fail-closed contract: only two outcomes permit generating fresh material —
159	/// `Ok(None)` for a genuinely absent slot, or for a slot staged under *different
160	/// ceremony inputs* (a new handle/PDS is a new ceremony; starting one is the user's
161	/// explicit abandonment of the old attempt, whose set can never bind to this
162	/// ceremony's genesis op). Every other defect — a transient read error, unparseable
163	/// JSON, an unsupported version, a corrupt envelope, cross-set envelopes, a failed
164	/// combine/derivation — is `Err(StagingCorrupt)`: the record may be the exact set a
165	/// prior attempt already bound to a genesis op and escrowed, so overwriting it with
166	/// unrelated shares would permanently destroy the recovery seed. The slot is
167	/// preserved for a later retry or manual inspection.
168	fn load_staged(
169	    handle: &str,
170	    pds_url: &str,
171	) -> Result<Option<CeremonyShareSet>, ShareCeremonyError> {
172	    let bytes = match keychain::get_item(STAGING_ACCOUNT) {
173	        Ok(bytes) => Zeroizing::new(bytes),
174	        Err(e) if keychain::is_not_found(&e) => return Ok(None),
175	        Err(e) => {
176	            tracing::error!(error = %e, "ceremony staging slot unreadable; failing closed");
177	            return Err(ShareCeremonyError::StagingCorrupt(format!(
178	                "keychain read failed: {e}"
179	            )));
180	        }
181	    };
182	    let record: StagingRecord = serde_json::from_slice(&bytes).map_err(|e| {
183	        tracing::error!(error = %e, "ceremony staging record unparseable; failing closed");
184	        ShareCeremonyError::StagingCorrupt(format!("unparseable staging record: {e}"))
185	    })?;
186	    if record.version != STAGING_VERSION {
187	        tracing::error!(
188	            version = record.version,
189	            "ceremony staging record has unsupported version; failing closed"
190	        );
191	        return Err(ShareCeremonyError::StagingCorrupt(format!(
192	            "unsupported staging record version {}",
193	            record.version
194	        )));
195	    }
196	    if record.handle != handle || record.pds_url != pds_url {
197	        tracing::warn!(
198	            "ceremony inputs changed since staging; abandoning the staged set and regenerating"
199	        );
200	        return Ok(None);
201	    }
202	
203	    let decode = |encoded: &str, index: u8| -> Result<crypto::ShareEnvelope, ShareCeremonyError> {
204	        match crypto::ShareEnvelope::decode_share(encoded) {
205	            Ok(env) if env.index() == index => Ok(env),
206	            Ok(env) => {
207	                tracing::error!(
208	                    expected = index,
209	                    got = env.index(),
210	                    "staged share has wrong index; failing closed"
211	                );
212	                Err(ShareCeremonyError::StagingCorrupt(format!(
213	                    "staged share has index {} where {index} was expected",
214	                    env.index()
215	                )))
216	            }
217	            Err(e) => {
218	                tracing::error!(error = %e, "staged share failed validation; failing closed");
219	                Err(ShareCeremonyError::StagingCorrupt(format!(
220	                    "staged share failed validation: {e}"
221	                )))
222	            }
223	        }
224	    };
225	    let env1 = decode(&record.share1, 1)?;
226	    let env2 = decode(&record.share2, 2)?;
227	    let env3 = decode(&record.share3, 3)?;
228	    if env1.set_id() != env2.set_id() || env2.set_id() != env3.set_id() {
229	        tracing::error!("staged shares span set_ids; failing closed");
230	        return Err(ShareCeremonyError::StagingCorrupt(
231	            "staged shares span set_ids".to_string(),
232	        ));
233	    }
234	
235	    // The seed is not stored — recompute it to re-derive the recovery key.
236	    let seed = crypto::combine_envelopes(&env1, &env2).map_err(|e| {
237	        tracing::error!(error = %e, "staged shares failed to combine; failing closed");
238	        ShareCeremonyError::StagingCorrupt(format!("staged shares failed to combine: {e}"))
239	    })?;
240	    let recovery = crypto::derive_recovery_keypair(&seed).map_err(|e| {
241	        tracing::error!(error = %e, "recovery key derivation failed on staged seed; failing closed");
242	        ShareCeremonyError::StagingCorrupt(format!("recovery key derivation failed: {e}"))
243	    })?;
244	
245	    tracing::info!(set_id = env1.set_id(), "reusing staged ceremony share set");
246	    Ok(Some(CeremonyShareSet {
247	        recovery_key_id: recovery.key_id.0,
248	        share1: env1.encode_share(),
249	        share2: env2.encode_share(),
250	        share3: env3.encode_share(),
251	        share3_words: env3.encode_share_words(),
252	    }))
253	}
254	
255	/// Tear down the staging slot — the seed material's last transient home. Idempotent:
256	/// an absent slot is success (the teardown already happened).
257	pub fn clear_staging() -> Result<(), keychain::KeychainError> {
258	    match keychain::delete_item(STAGING_ACCOUNT) {
259	        Ok(()) => Ok(()),
260	        Err(e) if keychain::is_not_found(&e) => Ok(()),
261	        Err(e) => Err(e),
262	    }
263	}
264	
265	#[cfg(test)]
266	mod tests {
267	    use super::*;
268	
269	    const HANDLE: &str = "alice.example.com";
270	    const PDS: &str = "https://pds.example.com";
271	
272	    #[test]
273	    fn generates_and_stages_a_valid_set() {
274	        keychain::clear_for_test();
275	        let set = load_or_create(HANDLE, PDS).unwrap();
276	
277	        // All three envelopes decode, share the same set_id, and carry their indices.
278	        let env1 = crypto::ShareEnvelope::decode_share(&set.share1).unwrap();
279	        let env2 = crypto::ShareEnvelope::decode_share(&set.share2).unwrap();
280	        let env3 = crypto::ShareEnvelope::decode_share(&set.share3).unwrap();
281	        assert_eq!(env1.index(), 1);
282	        assert_eq!(env2.index(), 2);
283	        assert_eq!(env3.index(), 3);
284	        assert_eq!(env1.set_id(), env2.set_id());
285	        assert_eq!(env2.set_id(), env3.set_id());
286	
287	        // The word phrase encodes the same envelope as the base32 form.
288	        let from_words = crypto::ShareEnvelope::decode_share_words(&set.share3_words).unwrap();
289	        assert_eq!(from_words.set_id(), env3.set_id());
290	        assert_eq!(from_words.index(), 3);
291	
292	        // Any two shares reconstruct a seed whose derived key matches the declared one.
293	        let seed = crypto::combine_envelopes(&env1, &env3).unwrap();
294	        let derived = crypto::derive_recovery_keypair(&seed).unwrap();
295	        assert_eq!(derived.key_id.0, set.recovery_key_id);
296	    }
297	
298	    #[test]
299	    fn retry_reuses_the_staged_set() {
300	        keychain::clear_for_test();
301	        let first = load_or_create(HANDLE, PDS).unwrap();
302	        let second = load_or_create(HANDLE, PDS).unwrap();
303	        assert_eq!(*first.share1, *second.share1, "retry must reuse Share 1");
304	        assert_eq!(*first.share2, *second.share2, "retry must reuse Share 2");
305	        assert_eq!(*first.share3, *second.share3, "retry must reuse Share 3");
306	        assert_eq!(first.recovery_key_id, second.recovery_key_id);
307	        let set_id = |s: &str| crypto::ShareEnvelope::decode_share(s).unwrap().set_id();
308	        assert_eq!(
309	            set_id(&first.share2),
310	            set_id(&second.share2),
311	            "same set_id across retries — no orphaned escrow"
312	        );
313	    }
314	
315	    #[test]
316	    fn changed_ceremony_inputs_regenerate() {
317	        keychain::clear_for_test();
318	        let first = load_or_create(HANDLE, PDS).unwrap();
319	        let other = load_or_create("bob.example.com", PDS).unwrap();
320	        assert_ne!(
321	            *first.share2, *other.share2,
322	            "a different ceremony must not reuse the old set"
323	        );
324	    }
325	
326	    #[test]
327	    fn corrupt_staging_record_fails_closed_and_preserves_the_slot() {
328	        keychain::clear_for_test();
329	        load_or_create(HANDLE, PDS).unwrap();
330	        keychain::store_item(STAGING_ACCOUNT, b"not json").unwrap();
331	        // A present-but-unreadable record must never be overwritten with fresh
332	        // material — it may be the set a prior attempt already escrowed.
333	        // (CeremonyShareSet has no Debug — share material must not be printable.)
334	        let err = load_or_create(HANDLE, PDS)
335	            .map(|_| ())
336	            .expect_err("corrupt staging must fail closed");
337	        assert!(matches!(err, ShareCeremonyError::StagingCorrupt(_)));
338	        assert_eq!(
339	            keychain::get_item(STAGING_ACCOUNT).unwrap(),
340	            b"not json".to_vec(),
341	            "the staging slot must be preserved for inspection/retry"
342	        );
343	    }
344	
345	    #[test]
346	    fn tampered_staged_share_fails_closed() {
347	        keychain::clear_for_test();
348	        let first = load_or_create(HANDLE, PDS).unwrap();
349	        // Corrupt one envelope inside an otherwise valid record: the checksum check
350	        // must fail the load closed rather than regenerate. Flip share2's first
351	        // character to a different base32 character (deterministic corruption).
352	        let flipped_first = if first.share2.starts_with('A') {
353	            "B"
354	        } else {
355	            "A"
356	        };
357	        let mut corrupt_share2 = first.share2.to_string();
358	        corrupt_share2.replace_range(0..1, flipped_first);
359	        let bytes = keychain::get_item(STAGING_ACCOUNT).unwrap();
360	        let tampered = String::from_utf8(bytes)
361	            .unwrap()
362	            .replace(&*first.share2, &corrupt_share2);
363	        keychain::store_item(STAGING_ACCOUNT, tampered.as_bytes()).unwrap();
364	        assert!(matches!(
365	            load_or_create(HANDLE, PDS),
366	            Err(ShareCeremonyError::StagingCorrupt(_))
367	        ));
368	        // The envelope-validation failure path preserves the slot exactly like the
369	        // JSON-corruption path — the record is never overwritten with fresh material.
370	        assert_eq!(
371	            keychain::get_item(STAGING_ACCOUNT).unwrap(),
372	            tampered.as_bytes().to_vec(),
373	            "the tampered staging record must be preserved for inspection/retry"
374	        );
375	    }
376	
377	    #[test]
378	    fn clear_staging_is_idempotent() {
379	        keychain::clear_for_test();
380	        load_or_create(HANDLE, PDS).unwrap();
381	        clear_staging().unwrap();
382	        assert!(matches!(
383	            keychain::get_item(STAGING_ACCOUNT),
384	            Err(ref e) if keychain::is_not_found(e)
385	        ));
386	        clear_staging().unwrap();
387	    }
388	}
