2	  import { onMount } from 'svelte';
3	  import ScreenHeader from '$lib/components/ui/ScreenHeader.svelte';
4	  import Button from '$lib/components/ui/Button.svelte';
5	  import Spinner from '$lib/components/ui/Spinner.svelte';
6	  import SealEmblem from '$lib/components/ui/SealEmblem.svelte';
7	  import DiffRow from '$lib/components/ui/DiffRow.svelte';
8	  import { truncateDid } from '$lib/did-doc-utils';
9	  import {
10	    buildRepoKeyRotation,
11	    submitRepoKeyRotation,
12	    ensureIdentitySession,
13	    sovereignLogin,
14	    isCodedError,
15	    type SignedRotationOp,
16	    type RotationError,
17	  } from '$lib/ipc';
18	
19	  let {
20	    did,
21	    onback,
22	    ondone,
23	  }: {
24	    did: string;
25	    onback: () => void;
26	    /** Called after the rotation lands and the cache is refreshed. */
27	    ondone: () => void;
28	  } = $props();
29	
30	  type Phase =
31	    | { kind: 'loading' }
32	    | { kind: 'ready'; op: SignedRotationOp; error?: string }
33	    | { kind: 'load_error'; error: string }
34	    | { kind: 'working' }
35	    | { kind: 'success' };
36	
37	  let phase = $state<Phase>({ kind: 'loading' });
38	
39	  function messageFor(raw: unknown): string {
40	    if (!isCodedError(raw)) return 'Something went wrong. Please try again.';
41	    const err = raw as RotationError;
42	    switch (err.code) {
43	      case 'WALLET_NOT_AUTHORIZED':
44	        return 'This wallet isn’t authorized to rotate this identity’s signing key.';
45	      case 'SESSION_LOCKED':
46	        return 'Couldn’t unlock this identity. Please try again.';
47	      case 'RATE_LIMITED':
48	        return 'Too many attempts. Please wait a moment and try again.';
49	      case 'GUARD_REJECTED':
50	        return 'The rotation was blocked by a safety check and was not signed.';
51	      case 'ROTATION_FAILED':
52	        return 'The server rejected the rotation. Please try again.';
53	      case 'NETWORK_ERROR':
54	        return 'Couldn’t reach the server. Check your connection.';
55	      case 'NO_PENDING_ROTATION':
56	        return 'The prepared rotation expired. Go back and try again.';
57	      default:
58	        return 'Something went wrong. Please try again.';
59	    }
60	  }
61	
62	  /** Run `fn` with the session pre-flight: unlock passwordlessly once if locked. */
63	  async function withUnlockedSession<T>(fn: () => Promise<T>): Promise<T> {
64	    try {
65	      await ensureIdentitySession(did);
66	    } catch (e) {
67	      if (isCodedError(e) && e.code === 'NEEDS_UNLOCK') {
68	        await sovereignLogin(did);
69	      } else {
70	        throw e;
71	      }
72	    }
73	    try {
74	      return await fn();
75	    } catch (e) {
76	      // A live token can lapse between the pre-flight and the command. Unlock once and retry.
77	      if (isCodedError(e) && e.code === 'SESSION_LOCKED') {
78	        await sovereignLogin(did);
79	        return await fn();
80	      }
81	      throw e;
82	    }
83	  }
84	
85	  async function build() {
86	    phase = { kind: 'loading' };
87	    try {
88	      const op = await withUnlockedSession(() => buildRepoKeyRotation(did));
89	      phase = { kind: 'ready', op };
90	    } catch (e) {
91	      console.error('[RotateRepoKeyScreen] failed to build rotation:', e);
92	      phase = { kind: 'load_error', error: messageFor(e) };
93	    }
94	  }
95	
96	  async function submit() {
97	    if (phase.kind !== 'ready') return;
98	    const op = phase.op;
99	    phase = { kind: 'working' };
100	    try {
101	      await withUnlockedSession(() => submitRepoKeyRotation(did));
102	      phase = { kind: 'success' };
103	    } catch (e) {
104	      console.error('[RotateRepoKeyScreen] rotation failed:', e);
105	      phase = { kind: 'ready', op, error: messageFor(e) };
106	    }
107	  }
108	
109	  onMount(build);
110	</script>
111	
112	{#if phase.kind === 'success'}
113	  <div class="screen success">
114	    <SealEmblem>
115	      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /><path d="m9 11.5 2 2 4-4" /></svg>
116	    </SealEmblem>
117	    <h1 class="s-title">Signing key rotated</h1>
118	    <p class="s-body">
119	      Your hosting server now signs your data with a fresh key, and your identity record points at
120	      it. The old key no longer has any authority. It may take a few minutes to propagate across the
121	      network.
122	    </p>
123	    <Button onclick={ondone}>Done</Button>
124	  </div>
125	{:else}
126	  <div class="screen">
127	    <ScreenHeader title="Rotate signing key" onback={onback} backLabel="Back to identity" />
128	
129	    <p class="intro">
130	      Your hosting server holds a key that signs this identity’s data. Rotating replaces it with a
131	      freshly generated one — use this if you suspect the server’s key was exposed, or as periodic
132	      hygiene. Your device key is untouched and stays in control.
133	    </p>
134	
135	    <div class="identity">
136	      <span class="id-label">Identity</span>
137	      <span class="id-did">{truncateDid(did)}</span>
138	    </div>
139	
140	    {#if phase.kind === 'loading'}
141	      <div class="center">
142	        <Spinner size={28} label="Preparing the rotation" />
143	        <p class="hint">Requesting a fresh key and sealing the change…</p>
144	      </div>
145	    {:else if phase.kind === 'load_error'}
146	      <p class="status" role="alert">{phase.error}</p>
147	      <Button onclick={build}>Try again</Button>
148	    {:else if phase.kind === 'working'}
149	      <div class="center">
150	        <Spinner size={28} label="Rotating the signing key" />
151	        <p class="hint">Publishing the new key and switching over…</p>
152	      </div>
153	    {:else if phase.kind === 'ready'}
154	      <div class="block">
155	        <p class="block-label">This rotation will</p>
156	        {#each phase.op.diff.addedKeys as key}
157	          <DiffRow variant="restore" title="Install the fresh signing key" value={key} />
158	        {/each}
159	        {#each phase.op.diff.removedKeys as key}
160	          <DiffRow variant="remove" title="Retire the old signing key" value={key} />
161	        {/each}
162	      </div>
163	
164	      <div class="sealed">
165	        <span class="sealed-ic" aria-hidden="true"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /><path d="m9 11.5 2 2 4-4" /></svg></span>
166	        Sealed by your device key
167	      </div>
168	
169	      {#if phase.error}
170	        <div class="error-box" role="alert">
171	          <p class="error-text">{phase.error}</p>
172	        </div>
173	      {/if}
174	
175	      <div class="actions">
