  const deviceKeyId = fakeDeviceKeyId(did);
  const deviceKeyIsRoot = opts.deviceKeyIsRoot ?? true;
  const pdsKey = fakeDeviceKeyId(`${did}:pds`);
  const rotationKeys = deviceKeyIsRoot ? [deviceKeyId, pdsKey] : [pdsKey, deviceKeyId];
